INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q18469222', 'Portuguese campaigns of pacification and occupation', 'The Portuguese campaigns of pacification and occupation (Portuguese: Campanhas de pacificação e ocupação) were a vast set of military operations, conducted by the Portuguese Armed Forces in the overseas provinces of the Portuguese Empire, between 1838 and 1936. Action was seen at Chaimite, in Mozambique, where Mouzinho de Albuquerque captured the Vatua king Gungunhana but also at Môngua, in Angola.', 1880, NULL, NULL, 1920, NULL, NULL, 'decade', '1880s – 1920s', 30, 'https://en.wikipedia.org/wiki/Portuguese_campaigns_of_pacification_and_occupation'),
  ('Q1674550', 'Battle of the Cunene', 'The Battle of the Cunene took place between Portuguese colonial forces and Ovambo warriors from Oukwanyama and Cuamato in modern-day Angola on 25 September 1904. After having subdued the Nkhumbi people, Portuguese troops advanced from Huila southward into territories which were just claimed by Portugal but not yet under control.', 1904, 9, 25, NULL, NULL, NULL, 'day', '25 September 1904', 41, 'https://en.wikipedia.org/wiki/Battle_of_the_Cunene'),
  ('Q609836', 'Portuguese Colonial War', 'The Portuguese Colonial War (Portuguese: Guerra Colonial Portuguesa), also known in Portugal as the Overseas War (Guerra do Ultramar) or in the former colonies as the War of Liberation (Guerra de Libertação), and also known as the Angolan, Guinea-Bissau and Mozambican Wars of Independence, was a 13-year-long conflict fought between Portugal''s military and the emerging nationalist movements in Portugal''s African colonies between 1961 and 1974. The Portuguese regime at the time, the Estado Novo, was overthrown by a military coup in 1974, and the change in government brought the conflict to an…', 1961, 2, 4, 1974, 4, 25, 'day', '4 February 1961 – 25 April 1974', 69, 'https://en.wikipedia.org/wiki/Portuguese_Colonial_War'),
  ('Q152060', 'Cabinda Conflict', 'The Cabinda War is an ongoing separatist insurgency, waged by the Front for the Liberation of the Enclave of Cabinda (FLEC) against the government of Angola. FLEC aims at the restoration of the self-proclaimed Republic of Cabinda, located within the borders of the Cabinda province of Angola.', 1975, 11, 8, NULL, NULL, NULL, 'day', '8 November 1975', 57, 'https://en.wikipedia.org/wiki/Cabinda_War'),
  ('Q12055176', 'Angolan Civil War', 'The Angolan Civil War (Portuguese: Guerra Civil Angolana) was a civil war in Angola, beginning in 1975 and continuing, with interludes, until 2002. The war began immediately after Angola became independent from Portugal in November 1975.', 1975, 11, 11, 2002, 4, 4, 'day', '11 November 1975 – 4 April 2002', 74, 'https://en.wikipedia.org/wiki/Angolan_Civil_War'),
  ('Q7843235', 'Tripartite Accord', 'The Agreement among the People''s Republic of Angola, the Republic of Cuba, and the Republic of South Africa (also known as the Tripartite Accord, Three Powers Accord or New York Accords) granted independence to Namibia (then known as South West Africa) from South Africa and ended the direct involvement of foreign troops in the Angolan Civil War. The accords were signed on 22 December 1988 at the United Nations Headquarters in New York City by the Foreign Ministers of People''s Republic of Angola (Afonso Van-Dunem), Republic of Cuba (Isidoro Malmierca Peoli) and Republic of South Africa…', 1988, 12, 22, NULL, NULL, NULL, 'day', '22 December 1988', 34, 'https://en.wikipedia.org/wiki/Tripartite_Accord_(1988)'),
  ('Q5643106', 'Halloween Massacre', 'The Halloween Massacre (also known as the Three Day War) was a purge of UNITA party members and supporters carried out by Angola''s ruling MPLA from October 30 to November 1, 1992, in Luanda, Angola. The unrest occurred as a result of the breakdown of the Bicesse Accords, on account of alleged voter fraud in the 1992 Angolan general elections, resulting in renewed military tensions, assassinations of public figures, and acts of terrorism.', 1992, 10, 30, 1992, 11, 1, 'day', '30 October 1992 – 1 November 1992', 39, 'https://en.wikipedia.org/wiki/Halloween_Massacre_(Angola)'),
  ('Q3429692', '55 Day War', 'The 55-day war was a battle in the city of Huambo between the rebel forces of UNITA led by Arlindo Pena and the MPLA-led Angolan government. The 55-day war lasted between 9 January 1993 and 6 March 1993, resulting in UNITA emerging victorious and the destruction of most of the city.', 1993, 1, 9, 1993, 3, 6, 'day', '9 January 1993 – 6 March 1993', 39, 'https://en.wikipedia.org/wiki/55_Day_War'),
  ('Q838695', 'First Congo War', 'The First Congo War, also known as Africa''s First World War, was a civil and international military conflict that lasted from 24 October 1996 to 16 May 1997, primarily taking place in Zaire (which was renamed the Democratic Republic of the Congo during the conflict). The war resulted in the overthrow of Zairean President Mobutu Sese Seko, who was replaced by rebel leader Laurent-Désiré Kabila.', 1996, 10, 24, 1997, 5, 16, 'day', '24 October 1996 – 16 May 1997', 72, 'https://en.wikipedia.org/wiki/First_Congo_War'),
  ('Q75756', 'Second Congo War', 'The Second Congo War, also known as Africa''s World War or the Great War of Africa, was a major conflict that began on 2 August 1998 in the Democratic Republic of the Congo (DRC), just over a year after the First Congo War. The war initially erupted when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.', 1998, 8, 2, 2003, 6, 30, 'day', '2 August 1998 – 30 June 2003', 75, 'https://en.wikipedia.org/wiki/Second_Congo_War'),
  ('Q1021172', 'Republic of the Congo civil war', 'The Second Republic of the Congo Civil War, also known as the Second Brazzaville-Congolese Civil War, was the second of two ethnopolitical civil conflicts in the Republic of the Congo which lasted from 5 June 1997 to 29 December 1999. The war served as the continuation of the civil war of 1993–1994 and involved militias representing three political candidates.', 1999, 12, 29, 1999, NULL, NULL, 'day', '1999', 52, 'https://en.wikipedia.org/wiki/Republic_of_the_Congo_Civil_War_(1997%E2%80%931999)'),
  ('Q6952032', '2003 Angola Boeing 727 disappearance', 'On 25 May 2003, a Boeing 727 airliner, registered as N844AA, was stolen at Quatro de Fevereiro Airport in Luanda, Angola on the west-central coast of Southern Africa, prompting a worldwide search by law enforcement and intelligence agencies in the United States. No trace of the aircraft has ever been found.', 2003, 5, 25, NULL, NULL, NULL, 'day', '25 May 2003', 52, 'https://en.wikipedia.org/wiki/2003_Angola_Boeing_727_disappearance'),
  ('Q327237', 'Kivu conflict', 'The Kivu conflict, is an umbrella term for a series of protracted armed conflicts in the North Kivu and South Kivu provinces in the eastern Democratic Republic of the Congo which began after the Second Congo War ended. Including neighboring Ituri province, there are more than 120 different armed groups active in the eastern Democratic Republic of Congo.', 2004, 6, 2, NULL, NULL, NULL, 'day', '2 June 2004', 63, 'https://en.wikipedia.org/wiki/Kivu_conflict'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods');
